@tailwind base;
@tailwind components;
@tailwind utilities;

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

@layer base {
  html {
    font-family: 'Inter', system-ui, sans-serif;
  }
  body {
    @apply bg-page text-[#172B3A] antialiased;
  }
  * {
    box-sizing: border-box;
  }
}

@layer components {
  /* Status badge variants */
  .badge-normal    { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-green-100 text-green-800; }
  .badge-warning   { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-amber-100 text-amber-800; }
  .badge-critical  { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-red-100 text-red-800; }
  .badge-offline   { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-600; }
  .badge-occupied  { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-blue-100 text-blue-800; }
  .badge-fault     { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-red-100 text-red-800; }
  .badge-unknown   { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-500; }
  .badge-verify    { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-purple-100 text-purple-800; }

  /* Card */
  .card { @apply bg-white rounded-lg border border-[#D9E1E8] shadow-sm; }
  .card-header { @apply px-5 py-4 border-b border-[#D9E1E8]; }
  .card-body { @apply px-5 py-4; }

  /* Table */
  .data-table { @apply w-full text-sm; }
  .data-table th { @apply text-left text-xs font-semibold text-[#64748B] uppercase tracking-wider py-3 px-4 bg-[#F5F7FA] border-b border-[#D9E1E8]; }
  .data-table td { @apply py-3 px-4 border-b border-[#D9E1E8] text-[#172B3A]; }
  .data-table tr:last-child td { @apply border-b-0; }
  .data-table tr:hover td { @apply bg-[#F5F7FA]; }

  /* Buttons */
  .btn-primary { @apply inline-flex items-center gap-2 px-4 py-2 bg-[#145DA0] text-white text-sm font-medium rounded-md hover:bg-[#0B1F33] transition-colors; }
  .btn-secondary { @apply inline-flex items-center gap-2 px-4 py-2 bg-white text-[#145DA0] text-sm font-medium rounded-md border border-[#145DA0] hover:bg-[#EBF3FB] transition-colors; }
  .btn-danger { @apply inline-flex items-center gap-2 px-4 py-2 bg-[#DC2626] text-white text-sm font-medium rounded-md hover:bg-red-700 transition-colors; }
  .btn-ghost { @apply inline-flex items-center gap-2 px-3 py-1.5 text-[#64748B] text-sm font-medium rounded-md hover:bg-[#F5F7FA] transition-colors; }

  /* Section header */
  .section-title { @apply text-lg font-semibold text-[#172B3A]; }
  .section-subtitle { @apply text-sm text-[#64748B]; }

  /* Simulated data notice */
  .sim-notice { @apply inline-flex items-center gap-1 text-xs text-[#64748B] bg-[#F5F7FA] border border-[#D9E1E8] px-2 py-0.5 rounded; }
}

/* Scrollbar */
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: #F5F7FA; }
::-webkit-scrollbar-thumb { background: #D9E1E8; border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #9DB9CF; }

// ============================================================
// REGEN Railway Infrastructure Monitoring Platform
// TypeScript Type Definitions
// ============================================================

export type TCStatus = 'NORMAL' | 'OCCUPIED' | 'FAULT' | 'UNKNOWN' | 'OFFLINE';
export type TCOccupancy = 'CLEAR' | 'OCCUPIED' | 'UNKNOWN';
export type SectionStatus = 'OPERATIONAL' | 'DEGRADED' | 'SUSPENDED' | 'MAINTENANCE' | 'OFFLINE';
export type LineStatus = 'OPERATIONAL' | 'SUSPENDED' | 'MAINTENANCE' | 'OFFLINE';
export type SignalStatus = 'CLEAR' | 'CAUTION' | 'DANGER' | 'UNKNOWN' | 'OFFLINE';
export type AssetCondition = 'GOOD' | 'FAIR' | 'WARNING' | 'CRITICAL' | 'UNKNOWN';
export type AssetType =
  | 'COMPOSITE_SLEEPER' | 'STEEL_RAIL' | 'BRIDGE' | 'CULVERT'
  | 'BALLAST_BED' | 'SWITCH_ASSEMBLY' | 'LEVEL_CROSSING'
  | 'RETAINING_WALL' | 'EMBANKMENT' | 'VIADUCT';
export type SensorStatus = 'ACTIVE' | 'WARNING' | 'FAULT' | 'OFFLINE' | 'CALIBRATING';
export type RiskLevel = 'NORMAL' | 'SIMULATED_WARNING' | 'SIMULATED_CRITICAL' | 'OFFLINE' | 'UNKNOWN';
export type AlertPriority = 'NORMAL' | 'WARNING' | 'HIGH' | 'CRITICAL' | 'OFFLINE' | 'REQUIRES_VERIFICATION';
export type AlertStatus = 'OPEN' | 'ACKNOWLEDGED' | 'INVESTIGATING' | 'RESOLVED' | 'CLOSED' | 'FALSE_ALARM';
export type AlertSource = 'TRACK_CIRCUIT' | 'FBG_SENSOR' | 'ASSET' | 'COMMUNICATION' | 'MAINTENANCE' | 'COMBINED';
export type InspectionStatus = 'OPEN' | 'ASSIGNED' | 'IN_PROGRESS' | 'COMPLETED' | 'CANCELLED';
export type InspectionPriority = 'LOW' | 'NORMAL' | 'HIGH' | 'URGENT';
export type MaintenanceStatus =
  | 'OPEN' | 'ASSIGNED' | 'IN_PROGRESS' | 'COMPLETED'
  | 'VERIFICATION_REQUIRED' | 'VERIFIED' | 'CLOSED';
export type VerificationResult = 'PASSED' | 'FAILED' | 'PARTIAL' | 'REQUIRES_FOLLOW_UP';
export type TrendDirection = 'STABLE' | 'INCREASING' | 'DECREASING' | 'SUDDEN_CHANGE' | 'OFFLINE';

// ============================================================
// DATABASE ENTITY TYPES
// ============================================================

export interface Organisation {
  id: string;
  name: string;
  code: string;
  country: string;
  contact_email?: string;
  created_at: string;
}

export interface RailwayLine {
  id: string;
  organisation_id: string;
  name: string;
  code: string;
  description?: string;
  total_length_km?: number;
  status: LineStatus;
  created_at: string;
}

export interface Section {
  id: string;
  railway_line_id: string;
  name: string;
  code: string;
  description?: string;
  start_location?: string;
  end_location?: string;
  length_km?: number;
  status: SectionStatus;
  created_at: string;
  // joined
  railway_line?: RailwayLine;
}

export interface TrackCircuit {
  id: string;
  section_id: string;
  track_circuit_id: string;
  railway_line: string;
  location: string;
  status: TCStatus;
  occupancy: TCOccupancy;
  signal_relationship?: string;
  last_update: string;
  fault_status?: string;
  fault_description?: string;
  created_at: string;
  // joined
  section?: Section;
}

export interface Signal {
  id: string;
  section_id: string;
  track_circuit_id?: string;
  signal_id: string;
  signal_type: 'COLOUR_LIGHT' | 'SEMAPHORE' | 'DWARF' | 'SHUNTING';
  location: string;
  status: SignalStatus;
  created_at: string;
}

export interface Asset {
  id: string;
  section_id: string;
  track_circuit_id?: string;
  asset_id: string;
  asset_type: AssetType;
  description?: string;
  location: string;
  gps_lat?: number;
  gps_lon?: number;
  installation_date?: string;
  last_inspection?: string;
  condition: AssetCondition;
  created_at: string;
  // joined
  section?: Section;
  track_circuit?: TrackCircuit;
  fbg_sensors?: FBGSensor[];
  alerts?: Alert[];
}

export interface FBGSensor {
  id: string;
  asset_id: string;
  sensor_id: string;
  sensor_type: 'STRAIN' | 'TEMPERATURE' | 'DISPLACEMENT' | 'ACCELERATION';
  baseline_strain: number;
  current_strain?: number;
  wavelength_nm?: number;
  sensor_status: SensorStatus;
  risk_level: RiskLevel;
  install_date?: string;
  last_reading?: string;
  created_at: string;
  // computed
  deviation?: number;
  percentage_change?: number;
  trend?: TrendDirection;
  // joined
  asset?: Asset;
  recent_readings?: FBGReading[];
}

export interface FBGReading {
  id: string;
  sensor_id: string;
  timestamp: string;
  strain_value: number;
  wavelength?: number;
  temperature?: number;
  is_simulated: boolean;
}

export interface TrackCircuitEvent {
  id: string;
  track_circuit_id: string;
  timestamp: string;
  previous_status?: TCStatus;
  new_status: TCStatus;
  event_type: 'STATUS_CHANGE' | 'FAULT' | 'RECOVERY' | 'OFFLINE' | 'RECONNECT' | 'MANUAL_UPDATE';
  description?: string;
  is_simulated: boolean;
}

export interface Alert {
  id: string;
  alert_ref: string;
  source_type: AlertSource;
  priority: AlertPriority;
  title: string;
  description: string;
  track_circuit_id?: string;
  asset_id?: string;
  sensor_id?: string;
  section_id?: string;
  status: AlertStatus;
  acknowledged_by?: string;
  acknowledged_at?: string;
  resolved_at?: string;
  is_simulated: boolean;
  created_at: string;
  updated_at: string;
  // joined
  track_circuit?: TrackCircuit;
  asset?: Asset;
  sensor?: FBGSensor;
  section?: Section;
}

export interface Inspection {
  id: string;
  inspection_ref: string;
  alert_id?: string;
  asset_id: string;
  track_circuit_id?: string;
  sensor_id?: string;
  title: string;
  reason: string;
  priority: InspectionPriority;
  assigned_to?: string;
  inspector_name?: string;
  status: InspectionStatus;
  scheduled_date?: string;
  completed_date?: string;
  location?: string;
  findings?: string;
  fault_confirmed?: boolean;
  false_alarm: boolean;
  photos_count: number;
  recommendation?: string;
  created_at: string;
  updated_at: string;
  // joined
  asset?: Asset;
  alert?: Alert;
  track_circuit?: TrackCircuit;
  sensor?: FBGSensor;
}

export interface MaintenanceTask {
  id: string;
  maintenance_ref: string;
  inspection_id?: string;
  asset_id: string;
  alert_id?: string;
  title: string;
  fault_description: string;
  cause?: string;
  work_description?: string;
  assigned_technician?: string;
  priority: InspectionPriority;
  status: MaintenanceStatus;
  start_time?: string;
  completion_time?: string;
  created_at: string;
  updated_at: string;
  // joined
  asset?: Asset;
  inspection?: Inspection;
  verifications?: MaintenanceVerification[];
}

export interface MaintenanceVerification {
  id: string;
  maintenance_task_id: string;
  verified_by: string;
  verification_date: string;
  result: VerificationResult;
  notes?: string;
  post_strain_reading?: number;
  tc_status_confirmed?: string;
  created_at: string;
}

// ============================================================
// UI / COMPUTED TYPES
// ============================================================

export interface DashboardStats {
  totalSections: number;
  occupiedCircuits: number;
  tcFaults: number;
  infraWarnings: number;
  criticalAssets: number;
  fbgSensorStatus: { active: number; warning: number; fault: number; offline: number };
  activeAlerts: number;
  openMaintenance: number;
}

export interface NetworkMapNode {
  id: string;
  type: 'line' | 'section' | 'tc' | 'signal' | 'asset';
  label: string;
  status: string;
  x: number;
  y: number;
  children?: NetworkMapNode[];
}

export interface ChartDataPoint {
  timestamp: string;
  value: number;
  label?: string;
}

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || '';
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY || '';

export const supabase = createClient(supabaseUrl, supabaseAnonKey);

export const useMockData = import.meta.env.VITE_USE_MOCK_DATA === 'true';

