  .badge-warning  { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-amber-100 text-amber-800; }
  .badge-critical { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-red-100 text-red-800; }
  .badge-offline  { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-600; }
  .badge-occupied { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-blue-100 text-blue-800; }
  .badge-fault    { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-red-100 text-red-800; }
  .badge-unknown  { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-500; }
  .badge-verify   { @apply inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-purple-100 text-purple-800; }

  .card         { @apply bg-white rounded-lg border border-[#D9E1E8] shadow-sm; }
  .card-header  { @apply px-5 py-4 border-b border-[#D9E1E8]; }
  .card-body    { @apply px-5 py-4; }

  .data-table    { @apply w-full text-sm; }
  .data-table th { @apply text-left text-xs font-semibold text-[#64748B] uppercase tracking-wider py-3 px-4 bg-[#F5F7FA] border-b border-[#D9E1E8]; }
  .data-table td { @apply py-3 px-4 border-b border-[#D9E1E8] text-[#172B3A]; }
  .data-table tr:last-child td { @apply border-b-0; }
  .data-table tr:hover td { @apply bg-[#F5F7FA]; }

  .btn-primary   { @apply inline-flex items-center gap-2 px-4 py-2 bg-[#145DA0] text-white text-sm font-medium rounded-md hover:bg-[#0B1F33] transition-colors; }
  .btn-secondary { @apply inline-flex items-center gap-2 px-4 py-2 bg-white text-[#145DA0] text-sm font-medium rounded-md border border-[#145DA0] hover:bg-[#EBF3FB] transition-colors; }
  .btn-ghost     { @apply inline-flex items-center gap-2 px-3 py-1.5 text-[#64748B] text-sm font-medium rounded-md hover:bg-[#F5F7FA] transition-colors; }

  .section-title    { @apply text-lg font-semibold text-[#172B3A]; }
  .section-subtitle { @apply text-sm text-[#64748B]; }
}

::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: #F5F7FA; }
::-webkit-scrollbar-thumb { background: #D9E1E8; border-radius: 3px; }
::-webkit-scrollbar-thumb:hover { background: #9DB9CF; }

import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AppLayout } from './components/layout/AppLayout';
import { Dashboard } from './pages/Dashboard';
import { NetworkMap } from './pages/NetworkMap';
import { TrackCircuits } from './pages/TrackCircuits';
import { Assets } from './pages/Assets';
import { FBGMonitoring } from './pages/FBGMonitoring';
import { Alerts } from './pages/Alerts';
import { Inspections } from './pages/Inspections';
import { Maintenance } from './pages/Maintenance';
import { Reports } from './pages/Reports';

export default function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route element={<AppLayout />}>
          <Route index element={<Dashboard />} />
          <Route path="network" element={<NetworkMap />} />
          <Route path="track-circuits" element={<TrackCircuits />} />
          <Route path="track-circuits/:id" element={<TrackCircuits />} />
          <Route path="assets" element={<Assets />} />
          <Route path="assets/:id" element={<Assets />} />
          <Route path="fbg" element={<FBGMonitoring />} />
          <Route path="fbg/:id" element={<FBGMonitoring />} />
          <Route path="alerts" element={<Alerts />} />
          <Route path="alerts/:id" element={<Alerts />} />
          <Route path="inspections" element={<Inspections />} />
          <Route path="inspections/:id" element={<Inspections />} />
          <Route path="maintenance" element={<Maintenance />} />
          <Route path="maintenance/:id" element={<Maintenance />} />
          <Route path="reports" element={<Reports />} />
          <Route path="*" element={<Navigate to="/" replace />} />
        </Route>
      </Routes>
    </BrowserRouter>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { Activity, AlertTriangle, Package, Radio, Bell, Wrench, Layers, Zap } from 'lucide-react';
import { StatCard } from '../components/ui/StatCard';
import { SimBadge } from '../components/ui/SimBadge';
import { PageLoading } from '../components/ui/LoadingSpinner';
import { getDashboardStats, getAlerts, getTrackCircuits, getMaintenanceTasks } from '../lib/dataService';
import type { DashboardStats, Alert, TrackCircuit, MaintenanceTask } from '../types';
import { tcStatusBadge, alertPriorityBadge, alertStatusBadge, maintenanceStatusBadge, formatRelative } from '../lib/utils';

export function Dashboard() {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [alerts, setAlerts] = useState<Alert[]>([]);
  const [tcs, setTcs] = useState<TrackCircuit[]>([]);
  const [tasks, setTasks] = useState<MaintenanceTask[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([
      getDashboardStats(),
      getAlerts(['OPEN', 'INVESTIGATING', 'ACKNOWLEDGED']),
      getTrackCircuits(),
      getMaintenanceTasks(['OPEN', 'ASSIGNED', 'IN_PROGRESS', 'VERIFICATION_REQUIRED']),
    ]).then(([s, a, t, m]) => { setStats(s); setAlerts(a.slice(0, 8)); setTcs(t); setTasks(m.slice(0, 6)); })
      .finally(() => setLoading(false));
  }, []);

  if (loading || !stats) return <PageLoading />;
  const faultTCs = tcs.filter(tc => tc.status === 'FAULT' || tc.status === 'OFFLINE');

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3 p-3 bg-amber-50 border border-amber-200 rounded-lg">
        <AlertTriangle className="w-4 h-4 text-amber-600 flex-shrink-0" />
        <p className="text-sm text-amber-800">
          <strong>SIMULATED DATA — MVP PROTOTYPE.</strong> All data is fictional. REGEN is READ-ONLY and does not control real railway signals, track circuits or trains.
        </p>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard title="Total Track Sections" value={stats.totalSections} subtitle="Across 3 railway lines" icon={<Layers className="w-5 h-5" />} />
        <StatCard title="Occupied Circuits" value={stats.occupiedCircuits} subtitle="Active occupations" icon={<Activity className="w-5 h-5" />} valueColor="text-blue-700" />
        <StatCard title="TC Faults / Offline" value={stats.tcFaults} subtitle="Require attention" icon={<Zap className="w-5 h-5" />} valueColor={stats.tcFaults > 0 ? 'text-red-600' : 'text-green-600'} />
        <StatCard title="Infrastructure Warnings" value={stats.infraWarnings} subtitle={`${stats.criticalAssets} critical assets`} icon={<Package className="w-5 h-5" />} valueColor={stats.infraWarnings > 0 ? 'text-amber-600' : 'text-green-600'} />
        <StatCard title="Critical Assets" value={stats.criticalAssets} subtitle="Engineering review needed" icon={<Package className="w-5 h-5" />} valueColor={stats.criticalAssets > 0 ? 'text-red-600' : 'text-green-600'} />
        <StatCard title="FBG Active" value={stats.fbgSensorStatus.active} subtitle={`${stats.fbgSensorStatus.warning} warning · ${stats.fbgSensorStatus.fault} fault · ${stats.fbgSensorStatus.offline} offline`} icon={<Radio className="w-5 h-5" />} />
        <StatCard title="Active Alerts" value={stats.activeAlerts} subtitle="Open + investigating" icon={<Bell className="w-5 h-5" />} valueColor={stats.activeAlerts > 0 ? 'text-amber-600' : 'text-green-600'} />
        <StatCard title="Open Maintenance" value={stats.openMaintenance} subtitle="Tasks in progress" icon={<Wrench className="w-5 h-5" />} valueColor={stats.openMaintenance > 0 ? 'text-amber-600' : 'text-green-600'} />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
        <div className="xl:col-span-2 card">
          <div className="card-header flex items-center justify-between">
            <div><h2 className="section-title">Active Alerts</h2><p className="section-subtitle mt-0.5">Requires attention</p></div>
            <div className="flex items-center gap-2"><SimBadge /><Link to="/alerts" className="btn-ghost text-xs">View all →</Link></div>
          </div>
          <div className="divide-y divide-[#D9E1E8]">
            {alerts.length === 0 && <div className="px-5 py-8 text-center text-[#64748B] text-sm">No active alerts</div>}
            {alerts.map(alert => (
              <Link key={alert.id} to={`/alerts/${alert.id}`} className="block px-5 py-3 hover:bg-[#F5F7FA] transition-colors">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className={alertPriorityBadge(alert.priority)}>{alert.priority.replace('_', ' ')}</span>
                  <span className={alertStatusBadge(alert.status)}>{alert.status}</span>
                  <span className="text-xs text-[#64748B]">{alert.alert_ref}</span>
                </div>
                <p className="text-sm font-medium text-[#172B3A] mt-1 truncate">{alert.title}</p>
                <p className="text-xs text-[#64748B] mt-0.5">{formatRelative(alert.created_at)}</p>
              </Link>
            ))}
          </div>
        </div>

        <div className="card">
          <div className="card-header flex items-center justify-between">
            <div><h2 className="section-title">Track Circuits</h2><p className="section-subtitle mt-0.5">READ-ONLY snapshot</p></div>
            <Link to="/track-circuits" className="btn-ghost text-xs">All →</Link>
          </div>
          <div className="px-5 py-3 grid grid-cols-4 gap-2 border-b border-[#D9E1E8]">
            {[{l:'Normal',c:tcs.filter(t=>t.status==='NORMAL').length,col:'text-green-600'},{l:'Occupied',c:tcs.filter(t=>t.status==='OCCUPIED').length,col:'text-blue-700'},{l:'Fault',c:tcs.filter(t=>t.status==='FAULT').length,col:'text-red-600'},{l:'Offline',c:tcs.filter(t=>t.status==='OFFLINE').length,col:'text-gray-500'}].map(item=>(
              <div key={item.l} className="text-center"><div className={`text-xl font-bold ${item.col}`}>{item.c}</div><div className="text-[10px] text-[#64748B]">{item.l}</div></div>
            ))}
          </div>
          <div className="divide-y divide-[#D9E1E8]">
            {faultTCs.length === 0 ? <div className="px-5 py-4 text-sm text-[#64748B] text-center">All circuits nominal</div>
              : faultTCs.slice(0,6).map(tc => (
                <Link key={tc.id} to={`/track-circuits/${tc.id}`} className="flex items-center gap-3 px-5 py-3 hover:bg-[#F5F7FA] transition-colors">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2"><span className="text-sm font-semibold text-[#172B3A]">{tc.track_circuit_id}</span><span className={tcStatusBadge(tc.status)}>{tc.status}</span></div>
                    <p className="text-xs text-[#64748B] truncate">{tc.location}</p>
                  </div>
                </Link>
              ))
            }
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
        <div className="card">
          <div className="card-header flex items-center justify-between">
            <div><h2 className="section-title">Open Maintenance Tasks</h2><p className="section-subtitle mt-0.5">{tasks.length} tasks requiring action</p></div>
            <Link to="/maintenance" className="btn-ghost text-xs">All →</Link>
          </div>
          <div className="divide-y divide-[#D9E1E8]">
            {tasks.length === 0 && <div className="px-5 py-8 text-center text-sm text-[#64748B]">No open tasks</div>}
            {tasks.map(task => (
              <Link key={task.id} to={`/maintenance/${task.id}`} className="flex items-start gap-3 px-5 py-3 hover:bg-[#F5F7FA] transition-colors">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap"><span className={maintenanceStatusBadge(task.status)}>{task.status.replace('_',' ')}</span><span className="text-xs text-[#64748B]">{task.maintenance_ref}</span></div>
                  <p className="text-sm font-medium text-[#172B3A] mt-1 truncate">{task.title}</p>
                  {task.assigned_technician && <p className="text-xs text-[#64748B]">{task.assigned_technician}</p>}
                </div>
              </Link>
            ))}
          </div>
        </div>

        <div className="card border-l-4 border-l-[#145DA0]">
          <div className="card-header"><h2 className="section-title">Demo Scenario: TC-021 + FBG-00021</h2><p className="section-subtitle mt-0.5">Follow the complete REGEN workflow</p></div>
          <div className="card-body space-y-2">
            {[
              {n:'1',l:'TC-021 Communication Fault',to:'/track-circuits/30000000-0000-0000-0000-000000000021'},
              {n:'2',l:'FBG-00021 Increasing Strain (+144.8%)',to:'/fbg/60000000-0000-0000-0000-000000000021'},
              {n:'3',l:'Combined Alert ALT-2024-001',to:'/alerts/80000000-0000-0000-0000-000000000001'},
              {n:'4',l:'Asset COMPOSITE-SLEEPER-021',to:'/assets/50000000-0000-0000-0000-000000000021'},
              {n:'5',l:'Inspection INS-2024-001 In Progress',to:'/inspections/90000000-0000-0000-0000-000000000001'},
              {n:'6',l:'Maintenance MNT-2024-001 In Progress',to:'/maintenance/A0000000-0000-0000-0000-000000000001'},
            ].map(item => (
              <Link key={item.n} to={item.to} className="flex items-center gap-3 p-2.5 rounded-md bg-[#F5F7FA] hover:bg-[#EBF3FB] border border-[#D9E1E8] transition-colors">
                <span className="w-6 h-6 rounded-full bg-[#145DA0] text-white text-xs font-bold flex items-center justify-center flex-shrink-0">{item.n}</span>
                <span className="text-sm text-[#172B3A] font-medium">{item.l}</span>
                <span className="ml-auto text-[#145DA0] text-xs">→</span>
              </Link>
            ))}
            <p className="text-xs text-[#145DA0] bg-[#EBF3FB] p-3 rounded-md mt-2">TC-021 fault and FBG-00021 strain are separate, spatially-related evidence sources. REGEN does not auto-conclude causation.</p>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { PageLoading } from '../components/ui/LoadingSpinner';
import { SimBadge } from '../components/ui/SimBadge';
import { getRailwayLines, getSections, getTrackCircuits, getAssets } from '../lib/dataService';
import type { RailwayLine, Section, TrackCircuit, Asset } from '../types';
import { tcStatusBadge, conditionBadge, statusDot } from '../lib/utils';

function Dot({ status, size = 10 }: { status: string; size?: number }) {
  return <span style={{ display:'inline-block', width:size, height:size, borderRadius:'50%', backgroundColor:statusDot(status), flexShrink:0 }} />;
}

export function NetworkMap() {
  const [lines, setLines] = useState<RailwayLine[]>([]);
  const [sections, setSections] = useState<Section[]>([]);
  const [tcs, setTcs] = useState<TrackCircuit[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);
  const [loading, setLoading] = useState(true);
  const [expandedLine, setExpandedLine] = useState<string | null>('10000000-0000-0000-0000-000000000001');
  const [expandedSection, setExpandedSection] = useState<string | null>('20000000-0000-0000-0000-000000000004');

  useEffect(() => {
    Promise.all([getRailwayLines(), getSections(), getTrackCircuits(), getAssets()])
      .then(([l,s,t,a]) => { setLines(l); setSections(s); setTcs(t); setAssets(a); })
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <PageLoading />;

  const lineStatus = (line: RailwayLine) => {
    const secIds = sections.filter(s => s.railway_line_id === line.id).map(s => s.id);
    const lineTCs = tcs.filter(tc => secIds.includes(tc.section_id));
    if (lineTCs.some(tc => tc.status === 'FAULT')) return 'FAULT';
    if (lineTCs.some(tc => tc.status === 'OFFLINE')) return 'OFFLINE';
    if (lineTCs.some(tc => tc.status === 'OCCUPIED')) return 'OCCUPIED';
    return line.status;
  };

  const sectionStatus = (section: Section) => {
    const secTCs = tcs.filter(tc => tc.section_id === section.id);
    if (secTCs.some(tc => tc.status === 'FAULT')) return 'FAULT';
    if (secTCs.some(tc => tc.status === 'OFFLINE')) return 'OFFLINE';
    if (secTCs.some(tc => tc.status === 'OCCUPIED')) return 'OCCUPIED';
    return section.status;
  };

  return (
    <div className="space-y-6">
      <div className="card p-4">
        <div className="flex items-center justify-between flex-wrap gap-3">
          <div><h2 className="text-base font-semibold text-[#172B3A]">Railway Network Overview</h2><p className="text-sm text-[#64748B] mt-0.5">Click any element to drill down. <SimBadge /></p></div>
          <div className="flex items-center gap-4 flex-wrap text-xs text-[#64748B]">
            {[{l:'Normal',c:'#16A34A'},{l:'Occupied',c:'#145DA0'},{l:'Warning',c:'#F59E0B'},{l:'Fault',c:'#DC2626'},{l:'Offline',c:'#6B7280'}].map(x=>(
              <div key={x.l} className="flex items-center gap-1.5"><span className="w-3 h-3 rounded-full inline-block" style={{backgroundColor:x.c}} />{x.l}</div>
            ))}
          </div>
        </div>
      </div>

      <div className="space-y-4">
        {lines.map(line => {
          const lineSecs = sections.filter(s => s.railway_line_id === line.id);
          const isExp = expandedLine === line.id;
          return (
            <div key={line.id} className="card overflow-hidden">
              <button onClick={() => setExpandedLine(isExp ? null : line.id)} className="w-full flex items-center gap-3 px-5 py-4 hover:bg-[#F5F7FA] transition-colors text-left">
                <Dot status={lineStatus(line)} size={14} />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <span className="font-semibold text-[#172B3A]">{line.name}</span>
                    <span className="text-xs text-[#64748B] font-mono">{line.code}</span>
                    {line.status === 'MAINTENANCE' && <span className="badge-warning">MAINTENANCE</span>}
                  </div>
                  <p className="text-xs text-[#64748B] mt-0.5">{line.description} · {line.total_length_km} km · {lineSecs.length} sections</p>
                </div>
                <span className="text-[#64748B]">{isExp ? '▲' : '▼'}</span>
              </button>
              {isExp && (
                <div className="border-t border-[#D9E1E8]">
                  {lineSecs.map(sec => {
                    const secTCs = tcs.filter(tc => tc.section_id === sec.id);
                    const secAssets = assets.filter(a => a.section_id === sec.id);
                    const isSecExp = expandedSection === sec.id;
                    return (
                      <div key={sec.id} className="border-b border-[#D9E1E8] last:border-b-0">
                        <button onClick={() => setExpandedSection(isSecExp ? null : sec.id)} className="w-full flex items-center gap-3 px-8 py-3 hover:bg-[#F5F7FA] transition-colors text-left">
                          <Dot status={sectionStatus(sec)} size={10} />
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 flex-wrap">
                              <span className="text-sm font-medium text-[#172B3A]">{sec.name}</span>
                              <span className="text-xs text-[#64748B] font-mono">{sec.code}</span>
                              {sec.status !== 'OPERATIONAL' && <span className="badge-warning text-[10px]">{sec.status}</span>}
                            </div>
                            <p className="text-xs text-[#64748B]">{sec.start_location} → {sec.end_location} · {sec.length_km} km · {secTCs.length} TC · {secAssets.length} assets</p>
                          </div>
                          <span className="text-[#64748B] text-xs">{isSecExp ? '▲' : '▼'}</span>
                        </button>
                        {isSecExp && (
                          <div className="px-12 pb-4 space-y-3">
                            {secTCs.length > 0 && (
                              <div>
                                <p className="text-xs font-semibold text-[#64748B] uppercase tracking-wider mb-2">Track Circuits</p>
                                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
                                  {secTCs.map(tc => (
                                    <Link key={tc.id} to={`/track-circuits/${tc.id}`} className="flex items-center gap-2 p-2.5 rounded border border-[#D9E1E8] bg-white hover:bg-[#F5F7FA] hover:border-[#145DA0] transition-colors">
                                      <Dot status={tc.status} size={8} />
                                      <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-1.5"><span className="text-xs font-semibold text-[#172B3A]">{tc.track_circuit_id}</span><span className={`${tcStatusBadge(tc.status)} text-[10px]`}>{tc.status}</span></div>
                                        <p className="text-[10px] text-[#64748B] truncate">{tc.location}</p>
                                      </div>
                                    </Link>
                                  ))}
                                </div>
                              </div>
                            )}
                            {secAssets.length > 0 && (
                              <div>
                                <p className="text-xs font-semibold text-[#64748B] uppercase tracking-wider mb-2">Infrastructure Assets</p>
                                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
                                  {secAssets.map(asset => (
                                    <Link key={asset.id} to={`/assets/${asset.id}`} className="flex items-center gap-2 p-2.5 rounded border border-[#D9E1E8] bg-white hover:bg-[#F5F7FA] hover:border-[#145DA0] transition-colors">
                                      <Dot status={asset.condition} size={8} />
                                      <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-1.5"><span className="text-xs font-semibold text-[#172B3A]">{asset.asset_id}</span><span className={`${conditionBadge(asset.condition)} text-[10px]`}>{asset.condition}</span></div>
                                        <p className="text-[10px] text-[#64748B] truncate">{asset.asset_type.replace('_',' ')}</p>
                                      </div>
                                    </Link>
                                  ))}
                                </div>
                              </div>
                            )}
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>

      <div className="card p-4">
        <h3 className="text-sm font-semibold text-[#172B3A] mb-3">Network Status Summary</h3>
        <div className="grid grid-cols-2 sm:grid-cols-5 gap-3">
          {[{l:'Normal',c:tcs.filter(t=>t.status==='NORMAL').length,cls:'bg-green-100 text-green-800 border-green-200'},
            {l:'Occupied',c:tcs.filter(t=>t.status==='OCCUPIED').length,cls:'bg-blue-100 text-blue-800 border-blue-200'},
            {l:'Fault',c:tcs.filter(t=>t.status==='FAULT').length,cls:'bg-red-100 text-red-800 border-red-200'},
            {l:'Unknown',c:tcs.filter(t=>t.status==='UNKNOWN').length,cls:'bg-gray-100 text-gray-600 border-gray-200'},
            {l:'Offline',c:tcs.filter(t=>t.status==='OFFLINE').length,cls:'bg-gray-200 text-gray-600 border-gray-300'},
          ].map(item => (
            <div key={item.l} className={`rounded border ${item.cls} px-3 py-2 text-center`}>
              <div className="text-2xl font-bold">{item.c}</div>
              <div className="text-xs font-medium">{item.l}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { ArrowLeft, AlertTriangle, CheckCircle, Radio } from 'lucide-react';
import { PageLoading } from '../components/ui/LoadingSpinner';
import { SimBadge } from '../components/ui/SimBadge';
import { getTrackCircuits, getTrackCircuitEvents, getAssets, getFBGSensors } from '../lib/dataService';
import type { TrackCircuit, TrackCircuitEvent, Asset, FBGSensor } from '../types';
import { tcStatusBadge, formatRelative, formatTime } from '../lib/utils';

function TCTimeline({ events }: { events: TrackCircuitEvent[] }) {
  return (
    <div className="space-y-0">
      {events.map((event, i) => {
        const isLast = i === events.length - 1;
        const isFault = event.new_status === 'FAULT' || event.event_type === 'FAULT';
        return (
          <div key={event.id} className="flex gap-3">
            <div className="flex flex-col items-center">
              <div className={`w-8 h-8 rounded-full border-2 flex items-center justify-center flex-shrink-0 text-xs font-bold ${isFault ? 'bg-red-100 border-red-400 text-red-700' : event.new_status === 'NORMAL' ? 'bg-green-100 border-green-300 text-green-700' : event.new_status === 'OCCUPIED' ? 'bg-blue-100 border-blue-300 text-blue-700' : 'bg-gray-100 border-gray-300 text-gray-500'}`}>{i + 1}</div>
              {!isLast && <div className="w-px flex-1 bg-[#D9E1E8] mt-1" style={{ minHeight: 20 }} />}
            </div>
            <div className="pb-4 flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className={`text-xs font-bold px-2 py-0.5 rounded ${isFault ? 'bg-red-100 text-red-700' : event.new_status === 'NORMAL' ? 'bg-green-100 text-green-700' : event.new_status === 'OCCUPIED' ? 'bg-blue-100 text-blue-700' : 'bg-gray-100 text-gray-600'}`}>{event.new_status}</span>
                {event.previous_status && <span className="text-xs text-[#64748B]">(was {event.previous_status})</span>}
                <span className="text-xs text-[#64748B] font-mono">{formatTime(event.timestamp)}</span>
              </div>
              <p className="text-sm text-[#172B3A] mt-1">{event.description}</p>
              <p className="text-xs text-[#64748B] mt-0.5">{formatRelative(event.timestamp)}</p>
            </div>
          </div>
        );
      })}
    </div>
  );
}

function TCDetail({ tc }: { tc: TrackCircuit }) {
  const [events, setEvents] = useState<TrackCircuitEvent[]>([]);
  const [relAssets, setRelAssets] = useState<Asset[]>([]);
  const [fbg, setFbg] = useState<FBGSensor[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([getTrackCircuitEvents(tc.id), getAssets(), getFBGSensors()])
      .then(([evts, allAssets, allSensors]) => {
        setEvents(evts);
        const tcAssets = allAssets.filter(a => a.track_circuit_id === tc.id);
        setRelAssets(tcAssets);
        setFbg(allSensors.filter(s => tcAssets.some(a => a.id === s.asset_id)));
      }).finally(() => setLoading(false));
  }, [tc.id]);

  return (
    <div className="space-y-6">
      <Link to="/track-circuits" className="btn-ghost inline-flex"><ArrowLeft className="w-4 h-4" /> Back</Link>
      <div className={`card border-l-4 ${tc.status === 'FAULT' ? 'border-l-red-500' : tc.status === 'OFFLINE' ? 'border-l-gray-400' : tc.status === 'OCCUPIED' ? 'border-l-blue-500' : 'border-l-green-500'}`}>
        <div className="card-header flex items-start justify-between flex-wrap gap-3">
          <div>
            <div className="flex items-center gap-3 flex-wrap"><h2 className="text-xl font-bold text-[#172B3A]">{tc.track_circuit_id}</h2><span className={tcStatusBadge(tc.status)}>{tc.status}</span><SimBadge /></div>
            <p className="text-sm text-[#64748B] mt-1">{tc.location}</p>
          </div>
          {(tc.status === 'FAULT' || tc.status === 'OFFLINE') && (
            <div className="flex items-center gap-2 px-3 py-2 bg-red-50 border border-red-200 rounded text-red-700 text-sm"><AlertTriangle className="w-4 h-4 flex-shrink-0" />Physical verification required</div>
          )}
        </div>
        <div className="card-body">
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
            {[{l:'Status',v:tc.status},{l:'Occupancy',v:tc.occupancy},{l:'Railway Line',v:tc.railway_line},{l:'Signal',v:tc.signal_relationship??'—'},{l:'Fault Status',v:tc.fault_status??'None'}].map(item=>(
              <div key={item.l}><p className="text-xs font-semibold text-[#64748B] uppercase tracking-wider">{item.l}</p><p className="mt-1 text-sm font-medium text-[#172B3A]">{item.v}</p></div>
            ))}
          </div>
          {tc.fault_description && <div className="mt-4 p-3 bg-red-50 border border-red-200 rounded"><p className="text-xs font-semibold text-red-700 uppercase tracking-wider">Fault Description</p><p className="text-sm text-red-800 mt-1">{tc.fault_description}</p></div>}
          <div className="mt-4 p-3 bg-[#EBF3FB] border border-[#C8E0F5] rounded"><p className="text-xs text-[#145DA0]"><strong>READ-ONLY:</strong> REGEN receives simulated status information. It does not control track circuits or issue commands to the signalling system.</p></div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="card">
          <div className="card-header"><h3 className="section-title">Event Timeline</h3><p className="section-subtitle mt-0.5">State change history</p></div>
          <div className="card-body">{loading ? <p className="text-sm text-[#64748B]">Loading...</p> : events.length === 0 ? <p className="text-sm text-[#64748B]">No events</p> : <TCTimeline events={events} />}</div>
        </div>
        <div className="space-y-4">
          <div className="card">
            <div className="card-header"><h3 className="section-title">Related Assets</h3></div>
            <div className="divide-y divide-[#D9E1E8]">
              {relAssets.length === 0 ? <div className="px-5 py-4 text-sm text-[#64748B]">No linked assets</div>
                : relAssets.map(a => (
                  <Link key={a.id} to={`/assets/${a.id}`} className="flex items-center gap-3 px-5 py-3 hover:bg-[#F5F7FA] transition-colors">
                    <div className="flex-1 min-w-0"><p className="text-sm font-semibold text-[#172B3A]">{a.asset_id}</p><p className="text-xs text-[#64748B] truncate">{a.asset_type.replace('_',' ')}</p></div>
                    <span className={`text-xs px-2 py-0.5 rounded font-medium ${a.condition==='GOOD'?'bg-green-50 text-green-700':a.condition==='CRITICAL'?'bg-red-50 text-red-700':'bg-amber-50 text-amber-700'}`}>{a.condition}</span>
                  </Link>
                ))
              }
            </div>
          </div>
          {fbg.length > 0 && (
            <div className="card">
              <div className="card-header"><h3 className="section-title flex items-center gap-2"><Radio className="w-4 h-4 text-[#00A6C7]" />FBG Sensors (same zone)</h3><p className="text-xs text-[#64748B] mt-0.5">Independent evidence source — not the cause of TC fault</p></div>
              <div className="divide-y divide-[#D9E1E8]">
                {fbg.map(s => (
                  <Link key={s.id} to={`/fbg/${s.id}`} className="flex items-center gap-3 px-5 py-3 hover:bg-[#F5F7FA] transition-colors">
                    <div className="flex-1 min-w-0"><p className="text-sm font-semibold text-[#172B3A]">{s.sensor_id}</p><p className="text-xs text-[#64748B]">Current: {s.current_strain??'Offline'} µε · Trend: {s.trend??'—'}</p></div>
                    <span className={`text-xs px-2 py-0.5 rounded font-medium ${s.risk_level==='NORMAL'?'bg-green-50 text-green-700':s.risk_level==='SIMULATED_CRITICAL'?'bg-red-50 text-red-700':s.risk_level==='OFFLINE'?'bg-gray-50 text-gray-600':'bg-amber-50 text-amber-700'}`}>{s.risk_level.replace('_',' ')}</span>
                  </Link>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {(tc.status === 'FAULT' || tc.status === 'OFFLINE') && (
        <div className="card border border-amber-200 bg-amber-50">
          <div className="card-body">
            <p className="text-sm font-semibold text-amber-800 mb-3">Recommended actions for {tc.track_circuit_id} {tc.status}:</p>
            <div className="flex flex-wrap gap-3">
              <Link to={`/inspections?tc=${tc.id}`} className="btn-primary"><CheckCircle className="w-4 h-4" />Create Inspection Task</Link>
              <Link to="/alerts" className="btn-secondary"><AlertTriangle className="w-4 h-4" />View Related Alerts</Link>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export function TrackCircuits() {
  const { id } = useParams();
  const [tcs, setTcs] = useState<TrackCircuit[]>([]);
  const [selected, setSelected] = useState<TrackCircuit | null>(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('ALL');

  useEffect(() => {
    getTrackCircuits().then(data => {
      setTcs(data);
      if (id) setSelected(data.find(tc => tc.id === id || tc.track_circuit_id === id) ?? null);
    }).finally(() => setLoading(false));
  }, [id]);

  if (loading) return <PageLoading />;
  if (id) return selected ? <TCDetail tc={selected} /> : <div className="p-8 text-center text-[#64748B]">Track circuit not found.</div>;

  const filtered = filter === 'ALL' ? tcs : tcs.filter(tc => tc.status === filter);
  return (
    <div className="space-y-4">
      <div className="card p-4 flex items-center gap-2 flex-wrap">
        {['ALL','NORMAL','OCCUPIED','FAULT','UNKNOWN','OFFLINE'].map(s => (
          <button key={s} onClick={() => setFilter(s)} className={`text-xs px-3 py-1.5 rounded-full border font-medium transition-colors ${filter===s?'bg-[#145DA0] text-white border-[#145DA0]':'bg-white text-[#64748B] border-[#D9E1E8] hover:border-[#145DA0]'}`}>
            {s}{s!=='ALL'&&` (${tcs.filter(tc=>tc.status===s).length})`}
          </button>
        ))}
        <div className="ml-auto"><SimBadge /></div>
      </div>
      <div className="card overflow-hidden">
        <div className="overflow-x-auto">
          <table className="data-table">
            <thead><tr><th>Circuit ID</th><th>Status</th><th>Occupancy</th><th>Location</th><th>Railway Line</th><th>Signal</th><th>Last Update</th><th>Fault</th><th></th></tr></thead>
            <tbody>
              {filtered.map(tc => (
                <tr key={tc.id}>
                  <td className="font-mono font-semibold text-[#172B3A]">{tc.track_circuit_id}</td>
                  <td><span className={tcStatusBadge(tc.status)}>{tc.status}</span></td>
                  <td className="text-[#64748B]">{tc.occupancy}</td>
                  <td className="text-[#172B3A] max-w-xs truncate">{tc.location}</td>
                  <td className="text-[#64748B] text-xs">{tc.railway_line}</td>
                  <td className="font-mono text-[#00A6C7] text-xs">{tc.signal_relationship??'—'}</td>
                  <td className="text-[#64748B] text-xs whitespace-nowrap">{formatRelative(tc.last_update)}</td>
                  <td>{tc.fault_status?<span className="text-xs text-red-600 font-medium">{tc.fault_status}</span>:<span className="text-xs text-green-600">None</span>}</td>
                  <td><Link to={`/track-circuits/${tc.id}`} className="btn-ghost text-xs py-1">View →</Link></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

