        <StatCard
          label="Sensors Online"
          value={`${onlineSensors} / ${totalSensors}`}
          sub={`${totalSensors - onlineSensors} offline`}
          color={onlineSensors === totalSensors ? '#39FF14' : '#FFB020'}
        />
        <StatCard
          label="Predicted Issues"
          value={predictedIssues.length}
          sub="Requiring attention"
          color="#00D1FF"
          onClick={() => navigate('/assets')}
        />
      </div>

      {/* Main grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">

        {/* Active alerts */}
        <div className="panel lg:col-span-2">
          <div className="panel-header">
            <span className="section-title flex items-center gap-2">
              <AlertTriangle className="w-3.5 h-3.5 text-warning" />
              Active Alerts
            </span>
            <button onClick={() => navigate('/alerts')} className="btn-ghost">
              View all →
            </button>
          </div>
          <div className="divide-y divide-border">
            {sortedAlerts.length === 0 ? (
              <EmptyState icon="✓" title="No active alerts" subtitle="Network operating normally" />
            ) : sortedAlerts.map(alert => (
              <button
                key={alert.id}
                onClick={() => {
                  selectAsset(alert.assetId);
                  navigate('/map');
                }}
                className="w-full text-left px-4 py-3 hover:bg-surface2 transition-colors flex items-start gap-3"
              >
                <div
                  className="w-1 self-stretch rounded-full mt-0.5 flex-shrink-0"
                  style={{ background: SEVERITY_COLOR[alert.severity] }}
                />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <SeverityBadge level={alert.severity} />
                    <span className="text-xs font-mono text-text-dim">
                      {formatDistanceToNow(new Date(alert.createdAt), { addSuffix: true })}
                    </span>
                  </div>
                  <p className="text-sm font-mono text-text-primary truncate">{alert.title}</p>
                  <p className="text-xs text-text-dim mt-0.5 line-clamp-1">{alert.description}</p>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Right column */}
        <div className="space-y-4">
          {/* Predicted issues */}
          <div className="panel">
            <div className="panel-header">
              <span className="section-title flex items-center gap-2">
                <TrendingDown className="w-3.5 h-3.5 text-info" />
                Predicted Issues
              </span>
            </div>
            <div className="p-3 space-y-2">
              {predictedIssues.map(id => {
                const pred = getPredictionForAsset(id);
                if (!pred) return null;
                const asset = assets.find(a => a.id === id);
                return (
                  <button
                    key={id}
                    onClick={() => { selectAsset(id); navigate('/map'); }}
                    className="w-full text-left p-2.5 rounded border border-border hover:border-cyan/30 hover:bg-surface2 transition-all"
                  >
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-xs font-mono font-semibold text-text-primary">{asset?.name ?? id}</span>
                      <span
                        className="text-[10px] font-mono px-1.5 py-0.5 rounded"
                        style={{
                          color: pred.riskLevel === 'high' ? '#FF3B3B' : pred.riskLevel === 'medium' ? '#FFB020' : '#39FF14',
                          background: pred.riskLevel === 'high' ? 'rgba(255,59,59,0.1)' : pred.riskLevel === 'medium' ? 'rgba(255,176,32,0.1)' : 'rgba(57,255,20,0.1)',
                        }}
                      >
                        {pred.riskLevel.toUpperCase()}
                      </span>
                    </div>
                    <p className="text-xs text-text-dim truncate">{pred.issue}</p>
                    <p className="text-[10px] font-mono text-info mt-1">RUL: {pred.rulDays} days</p>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Recent work orders */}
          <div className="panel">
            <div className="panel-header">
              <span className="section-title flex items-center gap-2">
                <Wrench className="w-3.5 h-3.5 text-cyan" />
                Work Orders
              </span>
              <button onClick={() => navigate('/work-orders')} className="btn-ghost">All →</button>
            </div>
            <div className="divide-y divide-border">
              {openWorkOrders.length === 0 ? (
                <EmptyState title="No active work orders" />
              ) : openWorkOrders.slice(0, 4).map(wo => (
                <div key={wo.id} className="px-4 py-2.5">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-xs font-mono font-semibold text-cyan">{wo.id}</span>
                    <StatusPill status={wo.status} />
                  </div>
                  <p className="text-xs text-text-primary truncate">{wo.title}</p>
                  <p className="text-[10px] text-text-dim mt-0.5 font-mono">{wo.assignedTeam}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Critical assets strip */}
      {criticalAssets.length > 0 && (
        <div className="panel">
          <div className="panel-header">
            <span className="section-title flex items-center gap-2">
              <Radio className="w-3.5 h-3.5 text-critical" />
              Assets Requiring Attention
            </span>
          </div>
          <div className="flex gap-3 p-3 overflow-x-auto">
            {criticalAssets.map(asset => (
              <button
                key={asset.id}
                onClick={() => { selectAsset(asset.id); navigate('/map'); }}
                className="flex-shrink-0 p-3 rounded border border-border hover:border-cyan/30 hover:bg-surface2 transition-all text-left"
                style={{ minWidth: 150 }}
              >
                <div className="flex items-center gap-2 mb-1">
                  <SeverityBadge level={asset.severity} />
                </div>
                <p className="text-xs font-mono font-semibold text-text-primary mt-1">{asset.name}</p>
                <p className="text-[10px] text-text-dim">{asset.location.split(',')[0]}</p>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

function StatusPill({ status }: { status: string }) {
  const styles: Record<string, { color: string; bg: string }> = {
    open:        { color: '#FF3B3B', bg: 'rgba(255,59,59,0.12)' },
    in_progress: { color: '#00D1FF', bg: 'rgba(0,209,255,0.12)' },
    resolved:    { color: '#39FF14', bg: 'rgba(57,255,20,0.10)' },
    closed:      { color: '#666666', bg: 'rgba(102,102,102,0.12)' },
  };
  const s = styles[status] ?? styles.open;
  return (
    <span className="text-[10px] font-mono px-1.5 py-0.5 rounded" style={{ color: s.color, background: s.bg }}>
      {status.replace('_', ' ').toUpperCase()}
    </span>
  );
}

import { useRef, useState, useCallback } from 'react';
import { useAssets } from '../../context/AssetContext';
import { STATIONS } from '../../data/assets';
import { SEVERITY_COLOR } from '../../utils/severity';
import type { Sensor } from '../../types';

const VB_W = 900;
const VB_H = 520;

// Track segment definitions [x1,y1,x2,y2, lineId]
const TRACK_SEGMENTS = [
  // North–South mainline
  { x1: 140, y1: 60,  x2: 140, y2: 150, line: 'north-south' },
  { x1: 140, y1: 150, x2: 140, y2: 245, line: 'north-south' },
  { x1: 140, y1: 245, x2: 140, y2: 340, line: 'north-south' },
  { x1: 140, y1: 340, x2: 140, y2: 435, line: 'north-south' },
  // East–West mainline
  { x1: 140, y1: 435, x2: 280, y2: 435, line: 'east-west' },
  { x1: 280, y1: 435, x2: 420, y2: 435, line: 'east-west' },
  { x1: 420, y1: 435, x2: 560, y2: 435, line: 'east-west' },
  { x1: 560, y1: 435, x2: 700, y2: 435, line: 'east-west' },
  // City Loop — diagonal
  { x1: 420, y1: 435, x2: 420, y2: 245, line: 'loop' },
  { x1: 420, y1: 245, x2: 420, y2: 60,  line: 'loop' },
  // Connector Sandton ↔ Rosebank
  { x1: 140, y1: 435, x2: 280, y2: 435, line: 'east-west' },
  // OR Tambo spur
  { x1: 700, y1: 435, x2: 700, y2: 390, line: 'east-west' },
  { x1: 700, y1: 390, x2: 700, y2: 340, line: 'east-west' },
];

const LINE_COLOR: Record<string, string> = {
  'north-south': '#00FFC6',
  'east-west':   '#00D1FF',
  'loop':        '#FFB020',
};

interface SensorTooltipData {
  sensor: Sensor;
  x: number;
  y: number;
}

export function RailwayMap() {
  const { sensors, assets, selectedAsset, selectedSensor, selectAsset, selectSensor } = useAssets();
  const svgRef = useRef<SVGSVGElement>(null);
  const [tooltip, setTooltip] = useState<SensorTooltipData | null>(null);
  const [mapTransform, setMapTransform] = useState({ scale: 1, tx: 0, ty: 0 });

  // Focus map on an asset (smooth zoom toward asset position)
  const focusOnAsset = useCallback((assetId: string) => {
    const asset = assets.find(a => a.id === assetId);
    if (!asset || !svgRef.current) return;
    const { mapX, mapY } = asset;
    const targetScale = 1.15;
    const cx = VB_W / 2;
    const cy = VB_H / 2;
    const tx = cx - mapX * targetScale;
    const ty = cy - mapY * targetScale;
    setMapTransform({ scale: targetScale, tx, ty });
  }, [assets]);

  const handleSensorClick = useCallback((sensor: Sensor) => {
    selectSensor(sensor.id);
    focusOnAsset(sensor.assetId);
    setTooltip(null);
  }, [selectSensor, focusOnAsset]);

  const handleAssetClick = useCallback((assetId: string) => {
    selectAsset(assetId);
    focusOnAsset(assetId);
  }, [selectAsset, focusOnAsset]);

  const handleSensorHover = useCallback((sensor: Sensor, svgX: number, svgY: number) => {
    setTooltip({ sensor, x: svgX, y: svgY });
  }, []);

  const handleBgClick = useCallback(() => {
    selectAsset(null);
    setMapTransform({ scale: 1, tx: 0, ty: 0 });
    setTooltip(null);
  }, [selectAsset]);

  const transform = `translate(${mapTransform.tx}, ${mapTransform.ty}) scale(${mapTransform.scale})`;

  return (
    <div className="relative w-full h-full bg-bg overflow-hidden select-none">
      <svg
        ref={svgRef}
        viewBox={`0 0 ${VB_W} ${VB_H}`}
        className="w-full h-full"
        style={{ transition: 'transform 400ms cubic-bezier(0.4,0,0.2,1)' }}
        aria-label="Gautrain Network Map"
        role="img"
      >
        {/* Background grid */}
        <defs>
          <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
            <path d="M 40 0 L 0 0 0 40" fill="none" stroke="#1A1A1A" strokeWidth="0.5" />
          </pattern>
          <filter id="glow-green">
            <feGaussianBlur stdDeviation="2" result="blur" />
            <feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge>
          </filter>
          <filter id="glow-red">
            <feGaussianBlur stdDeviation="3" result="blur" />
            <feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge>
          </filter>
          <filter id="glow-amber">
            <feGaussianBlur stdDeviation="2" result="blur" />
            <feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge>
          </filter>
        </defs>

        <rect width={VB_W} height={VB_H} fill="url(#grid)" onClick={handleBgClick} cursor="default" />

        {/* Animated group for zoom */}
        <g style={{ transition: 'transform 400ms cubic-bezier(0.4,0,0.2,1)' }} transform={transform}>

          {/* Track lines */}
          {TRACK_SEGMENTS.map((seg, i) => {
            const color = LINE_COLOR[seg.line] ?? '#2A2A2A';
            return (
              <g key={i}>
                {/* Track shadow / glow */}
                <line
                  x1={seg.x1} y1={seg.y1} x2={seg.x2} y2={seg.y2}
                  stroke={color} strokeWidth="6" strokeOpacity="0.12"
                />
                {/* Main track */}
                <line
                  x1={seg.x1} y1={seg.y1} x2={seg.x2} y2={seg.y2}
                  stroke={color} strokeWidth="2.5" strokeOpacity="0.7"
                />
                {/* Rail detail lines */}
                <line
                  x1={seg.x1} y1={seg.y1} x2={seg.x2} y2={seg.y2}
                  stroke={color} strokeWidth="0.5" strokeOpacity="0.3"
                  strokeDasharray="4 8"
                />
              </g>
            );
          })}

          {/* Stations */}
          {STATIONS.map(station => (
            <g key={station.id}>
              {/* Station outer ring */}
              <circle cx={station.x} cy={station.y} r={10}
                fill="none"
                stroke={LINE_COLOR[station.lineId] ?? '#2A2A2A'}
                strokeWidth="1.5" strokeOpacity="0.5"
              />
              {/* Station fill */}
              <circle cx={station.x} cy={station.y} r={6}
                fill="#111111"
                stroke={LINE_COLOR[station.lineId] ?? '#2A2A2A'}
                strokeWidth="2"
              />
              {/* Station dot */}
              <circle cx={station.x} cy={station.y} r={2.5}
                fill={LINE_COLOR[station.lineId] ?? '#666'}
              />
              {/* Station label */}
              <text
                x={station.x + 14} y={station.y + 1}
                fontSize="9" fontFamily="JetBrains Mono, monospace"
                fill="#A0A0A0" dominantBaseline="middle"
              >
                {station.name}
              </text>
            </g>
          ))}

          {/* Asset markers (clickable zones around sensors) */}
          {assets.map(asset => {
            const assetSensors = sensors.filter(s => s.assetId === asset.id);
            if (assetSensors.length === 0) return null;
            const isSelected = selectedAsset?.id === asset.id;
            return (
              <rect
                key={asset.id}
                x={asset.mapX - 22} y={asset.mapY - 22}
                width={44} height={44}
                fill="transparent"
                rx={4}
                stroke={isSelected ? 'rgba(0,255,198,0.5)' : 'transparent'}
                strokeWidth="1"
                cursor="pointer"
                onClick={(e) => { e.stopPropagation(); handleAssetClick(asset.id); }}
              />
            );
          })}

          {/* Sensor nodes */}
          {sensors.map(sensor => {
            const color = SEVERITY_COLOR[sensor.severity];
            const r = sensor.severity === 'critical' ? 7 : sensor.severity === 'warning' ? 5.5 : 4.5;
            const isSelected = selectedSensor?.id === sensor.id;
            const filterId =
              sensor.severity === 'critical' ? 'glow-red'
              : sensor.severity === 'warning' ? 'glow-amber'
              : 'glow-green';

            return (
              <g key={sensor.id}>
                {/* Pulse ring for warning/critical */}
                {(sensor.severity === 'critical' || sensor.severity === 'warning') && (
                  <circle cx={sensor.mapX} cy={sensor.mapY} r={r + 4}
                    fill="none" stroke={color} strokeWidth="0.8" strokeOpacity="0.3"
                  >
                    <animate
                      attributeName="r"
                      values={`${r + 2};${r + 10};${r + 2}`}
                      dur={sensor.severity === 'critical' ? '1s' : '2s'}
                      repeatCount="indefinite"
                    />
                    <animate
                      attributeName="stroke-opacity"
                      values="0.4;0;0.4"
                      dur={sensor.severity === 'critical' ? '1s' : '2s'}
                      repeatCount="indefinite"
                    />
                  </circle>
                )}

                {/* Selected ring */}
                {isSelected && (
                  <circle cx={sensor.mapX} cy={sensor.mapY} r={r + 5}
                    fill="none" stroke="#00FFC6" strokeWidth="1.5" strokeOpacity="0.8"
                    strokeDasharray="3 3"
                  />
                )}

                {/* Sensor dot */}
                <circle
                  cx={sensor.mapX} cy={sensor.mapY} r={r}
                  fill={color}
                  filter={`url(#${filterId})`}
                  cursor="pointer"
                  role="button"
                  aria-label={`Sensor ${sensor.id} — ${sensor.severity}`}
                  onClick={(e) => { e.stopPropagation(); handleSensorClick(sensor); }}
                  onMouseEnter={() => handleSensorHover(sensor, sensor.mapX, sensor.mapY)}
                  onMouseLeave={() => setTooltip(null)}
                  style={{ transition: 'r 300ms' }}
                />

                {/* Sensor ID label */}
                <text
                  x={sensor.mapX + r + 3} y={sensor.mapY}
                  fontSize="7" fontFamily="JetBrains Mono, monospace"
                  fill="#666666" dominantBaseline="middle"
                  pointerEvents="none"
                >
                  {sensor.id.split('_').slice(1, 3).join('_')}
                </text>
              </g>
            );
          })}

          {/* Line legend */}
          {Object.entries(LINE_COLOR).map(([lineId, color], i) => {
            const labels: Record<string, string> = {
              'north-south': 'N–S Line',
              'east-west': 'E–W Line',
              'loop': 'City Loop',
            };
            return (
              <g key={lineId} transform={`translate(${VB_W - 110}, ${30 + i * 20})`}>
                <line x1={0} y1={6} x2={20} y2={6} stroke={color} strokeWidth="2.5" strokeOpacity="0.7" />
                <text x={26} y={6} fontSize="9" fontFamily="JetBrains Mono, monospace"
                  fill="#A0A0A0" dominantBaseline="middle">
                  {labels[lineId]}
                </text>
              </g>
            );
          })}
        </g>

        {/* Tooltip (rendered outside transform group, in SVG overlay coordinates) */}
        {tooltip && (() => {
          const { sensor } = tooltip;
          const svgEl = svgRef.current;
          if (!svgEl) return null;
          // Map sensor coordinates through current transform to screen-space SVG coords
          const tx = tooltip.x * mapTransform.scale + mapTransform.tx;
          const ty = tooltip.y * mapTransform.scale + mapTransform.ty;
          // Convert SVG units to viewBox-relative
          const bx = Math.min(tx + 12, VB_W - 160);
          const by = Math.max(ty - 90, 5);
          return (
            <g pointerEvents="none">
              <rect x={bx} y={by} width={155} height={110}
                rx={4} fill="#111111" stroke="rgba(0,255,198,0.35)" strokeWidth="0.75"
              />
              <text x={bx + 10} y={by + 18} fontSize="10" fontFamily="JetBrains Mono, monospace"
                fill="#00FFC6" fontWeight="600">
                {sensor.assetId}
              </text>
              <text x={bx + 10} y={by + 32} fontSize="8" fontFamily="JetBrains Mono, monospace" fill="#666">
                Sensor
              </text>
              <text x={bx + 10} y={by + 43} fontSize="9" fontFamily="JetBrains Mono, monospace" fill="#A0A0A0">
                {sensor.id}
              </text>
              <text x={bx + 10} y={by + 57} fontSize="8" fontFamily="JetBrains Mono, monospace" fill="#666">
                Status
              </text>
              <text x={bx + 10} y={by + 68} fontSize="9" fontFamily="JetBrains Mono, monospace"
                fill={SEVERITY_COLOR[sensor.severity]}>
                {sensor.severity.toUpperCase()}
              </text>
              <text x={bx + 10} y={by + 82} fontSize="8" fontFamily="JetBrains Mono, monospace" fill="#666">
                {sensor.type.charAt(0).toUpperCase() + sensor.type.slice(1)}
              </text>
              <text x={bx + 10} y={by + 95} fontSize="10" fontFamily="JetBrains Mono, monospace" fill="#F0F0F0"
                fontWeight="600">
                {sensor.currentValue.toFixed(2)}{sensor.unit}
              </text>
            </g>
          );
        })()}
      </svg>
    </div>
  );
}

import { useAssets } from '../../context/AssetContext';
import { useAuth } from '../../context/AuthContext';
import { hasPermission } from '../../utils/permissions';
import { sortBySeverity, SEVERITY_COLOR } from '../../utils/severity';
import { SeverityBadge, EmptyState } from '../ui';
import { formatDistanceToNow } from 'date-fns';
import { Bell, CheckCircle } from 'lucide-react';

interface Props {
  onAlertClick?: (assetId: string, sensorId?: string) => void;
}

export function AlertsPanel({ onAlertClick }: Props) {
  const { alerts, acknowledgeAlert, selectAsset, selectSensor } = useAssets();
  const { user } = useAuth();
  const canAck = user ? hasPermission(user.role, 'canAcknowledgeAlert') : false;

  const sorted = sortBySeverity(
    [...alerts].filter(a => a.status !== 'resolved')
  );

  const handleClick = (assetId: string, sensorId?: string) => {
    selectAsset(assetId);
    if (sensorId) selectSensor(sensorId);
    onAlertClick?.(assetId, sensorId);
  };

  return (
    <aside
      className="flex flex-col bg-surface border-l border-border flex-shrink-0 overflow-hidden"
      style={{ width: 300 }}
      aria-label="Alerts panel"
    >
      {/* Header */}
      <div className="px-4 py-3 border-b border-border flex items-center gap-2 flex-shrink-0">
        <Bell className="w-3.5 h-3.5 text-warning" />
        <span className="section-title">Alerts</span>
        <span
          className="ml-auto text-xs font-mono px-1.5 py-0.5 rounded"
          style={{
            color: alerts.filter(a => a.severity === 'critical' && a.status === 'active').length > 0
              ? '#FF3B3B' : '#A0A0A0',
            background: 'rgba(255,59,59,0.1)',
          }}
        >
          {alerts.filter(a => a.status === 'active').length} active
        </span>
      </div>

      {/* List */}
      <div className="flex-1 overflow-y-auto divide-y divide-border">
        {sorted.length === 0 ? (
          <EmptyState icon="✓" title="No active alerts" subtitle="Network operating normally" />
        ) : (
          sorted.map(alert => (
            <button
              key={alert.id}
              onClick={() => handleClick(alert.assetId, alert.sensorId)}
              className="w-full text-left px-3 py-3 hover:bg-surface2 transition-colors group"
            >
              <div className="flex items-start gap-2">
                {/* Severity stripe */}
                <div
                  className="w-0.5 self-stretch rounded-full mt-0.5 flex-shrink-0"
                  style={{ background: SEVERITY_COLOR[alert.severity] }}
                />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <SeverityBadge level={alert.severity} />
                    {alert.status === 'acknowledged' && (
                      <span className="text-[10px] font-mono text-text-dim px-1 border border-border rounded">
                        ACK
                      </span>
                    )}
                  </div>
                  <p className="text-xs font-mono font-semibold text-text-primary leading-snug">
                    {alert.title}
                  </p>
                  <p className="text-[10px] text-text-dim mt-1 line-clamp-2 leading-relaxed">
                    {alert.description}
                  </p>
                  <p className="text-[10px] text-text-dim mt-1.5 font-mono">
                    {formatDistanceToNow(new Date(alert.createdAt), { addSuffix: true })}
                  </p>

                  {/* Acknowledge button */}
                  {canAck && alert.status === 'active' && (
                    <button
                      onClick={e => {
                        e.stopPropagation();
                        acknowledgeAlert(alert.id, user?.name ?? 'Unknown');
                      }}
                      className="mt-2 flex items-center gap-1 text-[10px] font-mono text-text-dim
                        hover:text-cyan transition-colors opacity-0 group-hover:opacity-100"
                    >
                      <CheckCircle className="w-3 h-3" />
                      Acknowledge
                    </button>
                  )}
                </div>
              </div>
            </button>
          ))
        )}
      </div>
    </aside>
  );
}

import { useMemo } from 'react';
import {
  AreaChart, Area, XAxis, YAxis, CartesianGrid,
  Tooltip, ReferenceLine, ResponsiveContainer,
} from 'recharts';
import { format } from 'date-fns';
import { getReadingsForSensor } from '../../data/readings';
import { SEVERITY_COLOR } from '../../utils/severity';
import type { Sensor } from '../../types';

interface Props {
  sensor: Sensor;
}

const CustomTooltip = ({ active, payload, label }: {
  active?: boolean; payload?: { value: number }[]; label?: string;
}) => {
  if (!active || !payload?.length) return null;
  const val = payload[0]?.value ?? 0;
  return (
    <div className="bg-surface2 border border-border rounded px-3 py-2 text-xs font-mono">
      <p className="text-text-dim mb-1">{label}</p>
      <p className="text-text-primary font-semibold">{val.toFixed(3)}</p>
    </div>
  );
};

export function SensorGraph({ sensor }: Props) {
  const readings = useMemo(() => getReadingsForSensor(sensor.id), [sensor.id]);

  const chartData = useMemo(() =>
    readings.map(r => ({
      time: format(new Date(r.timestamp), 'HH:mm'),
      value: r.value,
    })),
    [readings]
  );

  const peak = readings.length ? Math.max(...readings.map(r => r.value)) : sensor.currentValue;
  const avg = readings.length
    ? readings.reduce((s, r) => s + r.value, 0) / readings.length
    : sensor.currentValue;

  const color = SEVERITY_COLOR[sensor.severity];

  if (readings.length === 0) {
    return (
      <div className="flex items-center justify-center h-24 text-xs text-text-dim font-mono">
        No historical data available
      </div>
    );
  }

  return (
    <div>
      {/* Stats row */}
      <div className="flex gap-4 mb-3">
        <div>
          <p className="text-[10px] text-text-dim font-mono uppercase tracking-wider">Peak</p>
          <p className="text-sm font-mono font-bold" style={{ color }}>
            {peak.toFixed(3)}{sensor.unit}
          </p>
        </div>
        <div>
          <p className="text-[10px] text-text-dim font-mono uppercase tracking-wider">Average</p>
          <p className="text-sm font-mono font-bold text-text-secondary">
            {avg.toFixed(3)}{sensor.unit}
          </p>
        </div>
        <div>
          <p className="text-[10px] text-text-dim font-mono uppercase tracking-wider">Current</p>
          <p className="text-sm font-mono font-bold" style={{ color }}>
            {sensor.currentValue.toFixed(3)}{sensor.unit}
          </p>
        </div>
      </div>

      {/* Chart */}
      <ResponsiveContainer width="100%" height={120}>
        <AreaChart data={chartData} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
          <defs>
            <linearGradient id={`grad-${sensor.id}`} x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor={color} stopOpacity={0.3} />
              <stop offset="95%" stopColor={color} stopOpacity={0.02} />
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="2 4" stroke="#1A1A1A" />
          <XAxis
            dataKey="time"
            tick={{ fontSize: 8, fill: '#444', fontFamily: 'JetBrains Mono' }}
            tickLine={false}
            axisLine={false}
            interval="preserveStartEnd"
          />
          <YAxis
            tick={{ fontSize: 8, fill: '#444', fontFamily: 'JetBrains Mono' }}
            tickLine={false}
            axisLine={false}
            domain={['auto', 'auto']}
          />
          <Tooltip content={<CustomTooltip />} />
          {/* Warning threshold line */}
          <ReferenceLine
            y={sensor.warningMax} stroke="#FFB020"
            strokeDasharray="3 3" strokeWidth={0.8}
            label={{ value: 'WARN', position: 'insideTopRight', fontSize: 7, fill: '#FFB020' }}
          />
          {/* Critical threshold line */}
          <ReferenceLine
            y={sensor.criticalMax} stroke="#FF3B3B"
            strokeDasharray="3 3" strokeWidth={0.8}
            label={{ value: 'CRIT', position: 'insideTopRight', fontSize: 7, fill: '#FF3B3B' }}
          />
          <Area
            type="monotone"
            dataKey="value"
            stroke={color}
            strokeWidth={1.5}
            fill={`url(#grad-${sensor.id})`}
            dot={false}
            activeDot={{ r: 3, fill: color }}
            isAnimationActive={false}
          />
        </AreaChart>
      </ResponsiveContainer>
    </div>
  );
}

import { useState, useCallback } from 'react';
import { useAssets } from '../../context/AssetContext';
import { useAuth } from '../../context/AuthContext';
import { useDemo } from '../../context/DemoContext';
import { hasPermission } from '../../utils/permissions';
import { getPredictionForAsset } from '../../data/predictions';
import { getWorkOrdersForAsset } from '../../data/workOrders';
import { MAINTENANCE_RECORDS } from '../../data/users';
import { SEVERITY_COLOR } from '../../utils/severity';
import { SeverityBadge, ExpandToggle, Divider } from '../ui';
import { SensorGraph } from './SensorGraph';
import { WorkOrderModal } from '../work-orders/WorkOrderModal';
import { X, Radio, TrendingUp, Wrench, Clock } from 'lucide-react';
import { format, formatDistanceToNow } from 'date-fns';
import type { Sensor } from '../../types';

function SensorRow({ sensor, isSelected, onClick }: {
  sensor: Sensor; isSelected: boolean; onClick: () => void;
}) {
  const color = SEVERITY_COLOR[sensor.severity];
  return (
    <button
      onClick={onClick}
      className={`w-full text-left p-2.5 rounded border transition-all mb-1 ${
        isSelected ? 'border-cyan/50 bg-cyan/5' : 'border-border hover:border-border/80 hover:bg-surface2'
      }`}
    >
      <div className="flex items-center justify-between">
        <div>
          <p className="text-xs font-mono font-semibold text-text-primary">{sensor.id}</p>
          <p className="text-[10px] font-mono text-text-dim capitalize mt-0.5">{sensor.type}</p>
        </div>
        <div className="text-right">
          <p className="text-sm font-mono font-bold" style={{ color }}>
            {sensor.status === 'offline' ? '—' : `${sensor.currentValue.toFixed(2)}${sensor.unit}`}
          </p>
          {sensor.status === 'offline' && (
            <p className="text-[10px] text-text-dim font-mono">OFFLINE</p>
          )}
        </div>
      </div>
    </button>
  );
}

export function AssetDetailPanel() {
  const { selectedAsset, selectedSensor, sensors, selectAsset, selectSensor } = useAssets();
  const { user } = useAuth();
  const { stage } = useDemo();

  const [sensorOpen, setSensorOpen] = useState(true);
  const [predOpen, setPredOpen] = useState(true);
  const [maintOpen, setMaintOpen] = useState(false);
  const [showWOModal, setShowWOModal] = useState(false);

  const canCreateWO = user ? hasPermission(user.role, 'canCreateWorkOrder') : false;

  const assetSensors = selectedAsset
    ? sensors.filter(s => s.assetId === selectedAsset.id)
    : [];

  const prediction = selectedAsset ? getPredictionForAsset(selectedAsset.id) : null;
  const maintenanceRecords = selectedAsset
    ? MAINTENANCE_RECORDS.filter(m => m.assetId === selectedAsset.id).slice(0, 3)
    : [];

  const handleSensorClick = useCallback((sensor: Sensor) => {
    selectSensor(selectedSensor?.id === sensor.id ? null : sensor.id);
  }, [selectedSensor, selectSensor]);

  // Show panel if we have a selected asset
  if (!selectedAsset) return null;

  const primarySensor = assetSensors.find(s => s.severity === 'critical')
    ?? assetSensors.find(s => s.severity === 'warning')
    ?? assetSensors[0];

  const activeSensor = selectedSensor ?? primarySensor;

  // Role-specific view content
  const roleView = () => {
    if (!user) return null;
    if (user.role === 'administrator') {
      return (
        <div className="p-3 rounded border border-border bg-surface2 text-xs font-mono space-y-1.5">
          <div className="data-row">
            <span className="data-label">Connection</span>
            <span className="text-green font-semibold">Online</span>
          </div>
          <div className="data-row">
            <span className="data-label">MQTT</span>
            <span className="text-cyan">Connected</span>
          </div>
          <div className="data-row">
            <span className="data-label">Last Data</span>
            <span className="data-value">
              {primarySensor ? format(new Date(primarySensor.lastUpdate), 'HH:mm') : '—'}
            </span>
          </div>
          <div className="data-row">
            <span className="data-label">Sensors</span>
            <span className="data-value">{assetSensors.length}</span>
          </div>
        </div>
      );
    }
    if (user.role === 'operations_manager') {
      return (
        <div className="p-3 rounded border border-border bg-surface2 text-xs font-mono space-y-1.5">
          <div className="data-row">
            <span className="data-label">Maintenance Status</span>
            <span className="text-warning">Required</span>
          </div>
          <div className="data-row">
            <span className="data-label">Operational Risk</span>
            <span style={{ color: prediction?.riskLevel === 'high' ? '#FF3B3B' : '#FFB020' }}>
              {prediction?.riskLevel?.toUpperCase() ?? 'MEDIUM'}
            </span>
          </div>
          <p className="text-text-dim mt-2">Work Order Required to dispatch maintenance team.</p>
        </div>
      );
    }
    // Maintenance engineer — full data
    return (
      <div className="p-3 rounded border border-border bg-surface2 text-xs font-mono space-y-1.5">
        {primarySensor && (
          <>
            <div className="data-row">
              <span className="data-label">{primarySensor.type}</span>
              <span className="font-bold" style={{ color: SEVERITY_COLOR[primarySensor.severity] }}>
                {primarySensor.currentValue.toFixed(2)}{primarySensor.unit}
              </span>
            </div>
          </>
        )}
        {prediction && (
          <div className="data-row">
            <span className="data-label">RUL</span>
            <span className="text-info">{prediction.rulDays} days</span>
          </div>
        )}
        <p className="text-text-dim mt-1">Inspect asset on-site to verify condition.</p>
      </div>
    );
  };

  return (
    <>
      <aside
        className="absolute right-0 top-0 bottom-0 flex flex-col bg-surface border-l border-border
          overflow-hidden z-20 animate-slide-in-right"
        style={{ width: 380 }}
        aria-label="Asset detail panel"
      >
        {/* ── Header ── */}
        <div className="panel-header flex-shrink-0" style={{ padding: '12px 16px' }}>
          <div className="flex items-start justify-between gap-2">
            <div className="flex-1 min-w-0">
              <p className="text-[10px] font-mono text-text-dim uppercase tracking-widest mb-0.5">
                {selectedAsset.type.toUpperCase()}
              </p>
              <h2 className="text-base font-mono font-bold text-text-primary leading-tight truncate">
                {selectedAsset.name}
              </h2>
              <p className="text-xs text-text-dim mt-0.5 truncate">{selectedAsset.location}</p>
            </div>
            <div className="flex items-center gap-2 flex-shrink-0">
              <SeverityBadge level={selectedAsset.severity} />
              <button
                onClick={() => selectAsset(null)}
                className="text-text-dim hover:text-text-primary transition-colors p-1 rounded hover:bg-surface2"
                aria-label="Close panel"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>

        {/* ── Scrollable body ── */}
        <div className="flex-1 overflow-y-auto">
          {/* Always visible: primary sensor summary */}
          {primarySensor && (
            <div className="px-4 pt-3 pb-2">
              <div className="grid grid-cols-2 gap-2 mb-3">
                <div className="p-2.5 rounded border border-border bg-surface2">
                  <p className="data-label mb-1">Sensor</p>
                  <p className="data-value text-[11px]">{primarySensor.id}</p>
                </div>
                <div className="p-2.5 rounded border border-border bg-surface2">
                  <p className="data-label mb-1">Last Update</p>
                  <p className="data-value text-[11px]">
                    {format(new Date(primarySensor.lastUpdate), 'HH:mm:ss')}
                  </p>
                </div>
              </div>

              {/* Role-specific primary info */}
              {roleView()}
            </div>
          )}

          <Divider className="mx-4" />

          {/* ── Sensor Data (expandable) ── */}
          <div className="px-4 py-2">
            <ExpandToggle open={sensorOpen} onClick={() => setSensorOpen(v => !v)} label="Sensor Data" />
            {sensorOpen && (
              <div className="mt-2 space-y-1">
                {assetSensors.map(sensor => (
                  <SensorRow
                    key={sensor.id}
                    sensor={sensor}
                    isSelected={selectedSensor?.id === sensor.id}
                    onClick={() => handleSensorClick(sensor)}
                  />
                ))}
                {assetSensors.length === 0 && (
                  <p className="text-xs text-text-dim font-mono py-2">No sensors attached to this asset.</p>
                )}

                {/* Graph for selected sensor */}
                {activeSensor && activeSensor.status !== 'offline' && (
                  <div className="mt-3 pt-3 border-t border-border">
                    <div className="flex items-center gap-2 mb-2">
                      <Radio className="w-3 h-3 text-cyan" />
                      <span className="text-[10px] font-mono text-text-dim uppercase tracking-wider">
                        {activeSensor.id} — {activeSensor.type}
                      </span>
                    </div>
                    <SensorGraph sensor={activeSensor} />
                  </div>
                )}
                {activeSensor?.status === 'offline' && (
                  <div className="mt-2 p-2 rounded border border-border text-xs font-mono text-text-dim">
                    <p className="font-semibold text-warning">Sensor Offline</p>
                    <p className="mt-1">Last Reading: {format(new Date(activeSensor.lastUpdate), 'HH:mm')}</p>
                  </div>
                )}
              </div>
            )}
          </div>

          <Divider className="mx-4" />

          {/* ── Prediction (expandable) ── */}
          <div className="px-4 py-2">
            <ExpandToggle open={predOpen} onClick={() => setPredOpen(v => !v)} label="Prediction" />
            {predOpen && (
              <div className="mt-2">
                {prediction ? (
                  <div
                    className="p-3 rounded border text-xs font-mono space-y-2.5"
                    style={{
                      borderColor: prediction.riskLevel === 'high' ? 'rgba(255,59,59,0.3)' : 'rgba(255,176,32,0.3)',
                      background: prediction.riskLevel === 'high' ? 'rgba(255,59,59,0.04)' : 'rgba(255,176,32,0.04)',
                    }}
                  >
                    <div className="flex items-center justify-between">
                      <span className="data-label">Risk</span>
                      <span
                        className="font-bold"
                        style={{
                          color: prediction.riskLevel === 'high' ? '#FF3B3B'
                            : prediction.riskLevel === 'medium' ? '#FFB020' : '#39FF14',
                        }}
                      >
                        {prediction.riskLevel.toUpperCase()}
                      </span>
                    </div>
                    <div>
                      <span className="data-label block mb-0.5">Potential Issue</span>
                      <span className="text-text-primary leading-snug">{prediction.issue}</span>
                    </div>
                    <div className="flex gap-4">
                      <div>
                        <span className="data-label block">Est. RUL</span>
                        <span className="text-info font-bold text-sm">{prediction.rulDays} DAYS</span>
                      </div>
                      <div>
                        <span className="data-label block">Failure Prob.</span>
                        <span
                          className="font-bold text-sm"
                          style={{ color: prediction.failureProbability > 60 ? '#FF3B3B' : '#FFB020' }}
                        >
                          {prediction.failureProbability}%
                        </span>
                      </div>
                    </div>
                    <div>
                      <span className="data-label block mb-0.5">Recommended Action</span>
                      <span className="text-text-secondary leading-snug">{prediction.recommendedAction}</span>
                    </div>
                  </div>
                ) : (
                  <p className="text-xs text-text-dim font-mono py-2">No prediction data available.</p>
                )}
              </div>
            )}
          </div>

          <Divider className="mx-4" />

          {/* ── Maintenance History (expandable) ── */}
          <div className="px-4 py-2">
            <ExpandToggle open={maintOpen} onClick={() => setMaintOpen(v => !v)} label="Maintenance" />
            {maintOpen && (
              <div className="mt-2 space-y-2">
                {maintenanceRecords.length === 0 ? (
                  <p className="text-xs text-text-dim font-mono py-2">No maintenance history.</p>
                ) : maintenanceRecords.map(record => (
                  <div key={record.id} className="p-2.5 rounded border border-border bg-surface2 text-xs font-mono">
                    <div className="flex items-center justify-between mb-1">
                      <span className="font-semibold text-text-primary">{record.type}</span>
                      <span className="text-text-dim">
                        {formatDistanceToNow(new Date(record.performedAt), { addSuffix: true })}
                      </span>
                    </div>
                    <p className="text-text-dim line-clamp-2">{record.description}</p>
                    <p className="text-text-dim mt-1">By: {record.performedBy}</p>
                    <span className={`mt-1 inline-block px-1.5 py-0.5 rounded text-[10px] ${
                      record.outcome === 'completed' ? 'bg-green/10 text-green' : 'bg-warning/10 text-warning'
                    }`}>
