    selectAsset(assetId);
    navigate('/map');
  };

  // Sort: critical first
  const sorted = [...assets].sort((a, b) => {
    const order = { critical: 0, warning: 1, info: 2, healthy: 3, offline: 4 };
    return order[a.severity] - order[b.severity];
  });

  return (
    <div className="h-full overflow-y-auto p-4">
